SELECT COALESCE(SUM(CASE
            WHEN start_time >= #{query.startTime}
             AND start_time < #{query.endTime} THEN 1 ELSE 0 END), 0) AS started,
       COALESCE(SUM(CASE
            WHEN start_time >= #{previousStartTime}
             AND start_time < #{query.startTime} THEN 1 ELSE 0 END), 0) AS previous_started,
       COALESCE(SUM(CASE
            WHEN end_time >= #{query.startTime}
             AND end_time < #{query.endTime}
             AND status IN (1, 2, 3) THEN 1 ELSE 0 END), 0) AS completed,
       COALESCE(SUM(CASE
            WHEN end_time >= #{previousStartTime}
             AND end_time < #{query.startTime}
             AND status IN (1, 2, 3) THEN 1 ELSE 0 END), 0) AS previous_completed,
       COALESCE(SUM(CASE WHEN status = 0 THEN 1 ELSE 0 END), 0) AS current_running,
       COALESCE(SUM(CASE
            WHEN end_time >= #{query.startTime}
             AND end_time < #{query.endTime}
             AND status = 1 THEN 1 ELSE 0 END), 0) AS approved,
       COALESCE(SUM(CASE
            WHEN end_time >= #{query.startTime}
             AND end_time < #{query.endTime}
             AND status = 2 THEN 1 ELSE 0 END), 0) AS rejected,
       COALESCE(SUM(CASE
            WHEN end_time >= #{query.startTime}
             AND end_time < #{query.endTime}
             AND status = 3 THEN 1 ELSE 0 END), 0) AS cancelled,
       COALESCE(SUM(CASE
            WHEN status = 0 AND start_time < #{longRunningBefore}
            THEN 1 ELSE 0 END), 0) AS long_running
FROM flow_instance
WHERE org_id = #{query.orgId}

SELECT bucket AS date,
       SUM(started) AS started,
       SUM(completed) AS completed
FROM (
    SELECT  AS bucket, 1 AS started, 0 AS completed
    FROM (
        SELECT start_time AS event_time
        FROM flow_instance
        WHERE org_id = #{query.orgId}
          AND start_time >= #{query.startTime}
          AND start_time < #{query.endTime}
    ) started_event
    UNION ALL
    SELECT  AS bucket, 0 AS started, 1 AS completed
    FROM (
        SELECT end_time AS event_time
        FROM flow_instance
        WHERE org_id = #{query.orgId}
          AND status IN (1, 2, 3)
          AND end_time >= #{query.startTime}
          AND end_time < #{query.endTime}
    ) completed_event
) trend_event
GROUP BY bucket
ORDER BY bucket
